import sys,json
sys.path.insert(0,'/opt/tools')
from rcb_client import Robot
r=Robot(); s=r.spec(); print(json.dumps({k:s.get(k) for k in ['protocol','action_types','default_cameras','proprio_layout','proprio_groups','control_hz','max_call_wall_s','budget','static','robot_spec','world','cameras']},indent=2)[:30000]);
